-- Editable role permission matrix, phase 1: where a role's permissions are kept, and the built-in roles.
--
-- Until now what a role may do was written in the server's code. This update adds the place to keep
-- it in the database, and fills in one built-in role for each of today's role names with exactly
-- what the code gives that role today (src/backend/scripts/permission-defaults.js works it out;
-- src/backend/test/permissionMatrix.test.js proves it for every role on every route and page).
--
-- Nothing reads these yet: the server keeps deciding from its code until a later phase switches it
-- over. No existing column is changed or removed, and no row of any other table is touched. Rows of
-- "Role" that already exist keep their name, display name and old "permissions" column.

ALTER TABLE "Role" ADD COLUMN IF NOT EXISTS "grants" JSONB NOT NULL DEFAULT '[]';
ALTER TABLE "Role" ADD COLUMN IF NOT EXISTS "audience" TEXT NOT NULL DEFAULT 'STAFF';
ALTER TABLE "Role" ADD COLUMN IF NOT EXISTS "branchScope" TEXT NOT NULL DEFAULT 'ASSIGNED';
ALTER TABLE "Role" ADD COLUMN IF NOT EXISTS "baseRole" TEXT;
ALTER TABLE "Role" ADD COLUMN IF NOT EXISTS "updatedById" TEXT;

DO $role_matrix_checks$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'Role_audience_check') THEN
    ALTER TABLE "Role" ADD CONSTRAINT "Role_audience_check" CHECK ("audience" IN ('STAFF', 'CUSTOMER', 'PARTNER'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'Role_branchScope_check') THEN
    ALTER TABLE "Role" ADD CONSTRAINT "Role_branchScope_check" CHECK ("branchScope" IN ('ALL', 'ASSIGNED', 'OWN'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'Role_grants_array_check') THEN
    ALTER TABLE "Role" ADD CONSTRAINT "Role_grants_array_check" CHECK (jsonb_typeof("grants") = 'array');
  END IF;
END
$role_matrix_checks$;

-- One permission granted to, or taken from, one person on top of their roles (used from phase 4).
CREATE TABLE IF NOT EXISTS "UserPermissionOverride" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "permission" TEXT NOT NULL,
    "effect" TEXT NOT NULL,
    "reason" TEXT NOT NULL,
    "createdById" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3),
    CONSTRAINT "UserPermissionOverride_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "UserPermissionOverride_effect_check" CHECK ("effect" IN ('GRANT', 'DENY')),
    CONSTRAINT "UserPermissionOverride_reason_check" CHECK (length(btrim("reason")) > 0),
    CONSTRAINT "UserPermissionOverride_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "UserPermissionOverride_userId_permission_key" ON "UserPermissionOverride" ("userId", "permission");
CREATE INDEX IF NOT EXISTS "UserPermissionOverride_userId_idx" ON "UserPermissionOverride" ("userId");

-- The application's own role (update 17) reads and writes rows of this table like any other.
DO $role_matrix_grant$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'steelwise_runtime') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON "UserPermissionOverride" TO steelwise_runtime;
  END IF;
END
$role_matrix_grant$;

